print(f"Total pairs assembled: {len(pairs)}")
assert len(pairs) == 20, f"Expected 20 pairs, got {len(pairs)}"

tiers = {"short": 0, "medium": 0, "long": 0}

for idx, pair in enumerate(pairs):
    raw = pair["raw_asr"]
    ref = pair["refined_text"]

    # ASCII check
    raw.encode("ascii")
    ref.encode("ascii")

    # Leakage check
    assert raw.strip().lower() not in eval_raws, f"Sample {idx+1} raw leaked into sft_eval.json!"
    assert ref.strip() not in eval_refs, f"Sample {idx+1} ref leaked into sft_eval.json!"

    # Validator check
    val_ok, val_reason = val_mod.validate_pair(pair)
    assert val_ok, f"Sample {idx+1} failed validate_pair: {val_reason}"

    # Cleaner check
    clean_obj, clean_reason = clean_mod.clean_sample(raw, ref)
    assert clean_obj is not None, f"Sample {idx+1} failed clean_sample: {clean_reason}"
    assert clean_reason == "kept", f"Sample {idx+1} cleaner status != kept: {clean_reason}"

    # Tier invariants
    words = len(ref.split())
    if words < 25:
        tiers["short"] += 1
        assert "\n" not in ref, f"Sample {idx+1} has newline in short tier!"
        assert len(re.split(r'[.!?]+', ref.strip())) <= 2, f"Sample {idx+1} has multiple sentences in short tier!"
    elif words < 90:
        tiers["medium"] += 1
        sentences = [s for s in re.split(r'[.!?]+', ref.strip()) if s.strip()]
        assert 1 <= len(sentences) <= 3, f"Sample {idx+1} has {len(sentences)} sentences in medium tier!"
    else:
        tiers["long"] += 1
        assert "\n\n" in ref, f"Sample {idx+1} has no paragraph break in long tier!"

# Batch validator check
batch_ok, batch_reason, batch_tiers = val_mod.validate_batch(pairs, min_short=4, min_medium=6, min_long=10)
assert batch_ok, f"Batch validation failed: {batch_reason}"

print(f"Validation passed successfully!")
print(f"Tier counts: {tiers}")

# Save to scratch/subagent_batch_88.json
out_file = "scratch/subagent_batch_88.json"
with open(out_file, "w", encoding="utf-8") as f:
    json.dump(pairs, f, ensure_ascii=False, indent=2)

print(f"Successfully saved 20 verified samples to {out_file}")
